const home = join(run, 'h'), profile = join(home, 'profiles/qa'), temp = join(run, 'tmp');
const store = join(run, 'pnpm-store');
[run, home, profile, temp, store].forEach(linux);
const { LOCALAPPDATA: windowsLocalData, USERPROFILE: windowsProfile } = process.env;
assert.ok(windowsLocalData && windowsProfile, 'Windows LOCALAPPDATA and USERPROFILE are required');
