"""Normalize release records at the input boundary.

Validation, identity (deduplication) and replay against the persisted
journal live here; graph ordering lives in the planner.
"""
import heapq


class JournalError(ValueError):
    pass


def _string(value):
    return isinstance(value, str) and bool(value)


def _ids(value):
    """Return a canonical (sorted) list of distinct change IDs.

    Order and repetition carry no meaning, so duplicates that differ only in
    ordering still compare equal.
    """
    if not isinstance(value, list):
        raise JournalError("invalid-change")
    ids = set()
    for item in value:
        if not _string(item):
            raise JournalError("invalid-change")
        ids.add(item)
    return sorted(ids)


def read_changes(records):
    """Validate and collapse identical duplicate change records.

    Records with the same ID collapse to one when id, component, units and the
    set of dependencies all agree; otherwise the result is conflicting-change.
    """
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = {}
    for row in records:
        if not isinstance(row, dict):
            raise JournalError("invalid-change")
        change_id = row.get("id")
        component = row.get("component")
        units = row.get("units")
        if (not _string(change_id) or not _string(component)
                or type(units) is not int or units < 1):
            raise JournalError("invalid-change")
        depends_on = _ids(row.get("depends_on", []))
        change = {
            "id": change_id,
            "component": component,
            "units": units,
            "depends_on": depends_on,
        }
        known = changes.get(change_id)
        if known is None:
            changes[change_id] = change
        elif known != change:
            raise JournalError("conflicting-change")
    return list(changes.values())


def read_applied(value, records):
    """Resolve the persisted journal into a set of known change IDs."""
    applied = _ids(value)
    known = {row["id"] for row in records}
    for change_id in applied:
        if change_id not in known:
            raise JournalError("unknown-dependency")
    return set(applied)


def dependencies_known(changes):
    """Fail when any dependency names a change absent from the graph."""
    known = {row["id"] for row in changes}
    for row in changes:
        for dependency in row["depends_on"]:
            if dependency not in known:
                raise JournalError("unknown-dependency")


def topological_order(changes):
    """Kahn's algorithm with lexicographic tie-breaking among eligible IDs."""
    known = {row["id"] for row in changes}
    pending = {row["id"]: set(row["depends_on"]) for row in changes}
    dependents = {row["id"]: [] for row in changes}
    for row in changes:
        for dependency in pending[row["id"]]:
            dependents[dependency].append(row["id"])
    eligible = [change_id for change_id, deps in pending.items() if not deps]
    heapq.heapify(eligible)
    order = []
    while eligible:
        change_id = heapq.heappop(eligible)
        order.append(change_id)
        for dependent in dependents[change_id]:
            remaining = pending[dependent]
            remaining.discard(change_id)
            if not remaining:
                heapq.heappush(eligible, dependent)
    if len(order) != len(known):
        raise JournalError("dependency-cycle")
    return order

