"""Compose policy and journal data into a plan."""
from journal import (
    JournalError,
    dependencies_known,
    read_applied,
    read_changes,
    read_retain,
    topological_order,
)
from policy import PolicyError, freeze, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def success(actions, units):
    return {"status": "ok", "actions": actions, "units": units}


def retained_set(retain, applied, changes):
    """Expand retain with the applied transitive dependencies it requires.

    Locked IDs stay applied, so they cannot be rolled back; every applied
    change reachable through their dependencies must remain as well.
    """
    parents = {row["id"]: row["depends_on"] for row in changes}
    locked = set()
    stack = [change_id for change_id in retain]
    while stack:
        for dependency in parents[stack.pop()]:
            if dependency in applied and dependency not in locked:
                locked.add(dependency)
                stack.append(dependency)
    return locked | set(retain)


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        freeze(request)
        budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        dependencies_known(changes)
        applied = read_applied(request.get("applied", []), changes)
        order = topological_order(changes)
        # Retain is a rollback-only field; plans ignore it.
        if request.get("action") == "rollback":
            retain = read_retain(request.get("retain"), applied)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    units_by_id = {row["id"]: row["units"] for row in changes}
    if request.get("action") == "rollback":
        # Budget is validated but does not cap rollback.
        locked = retained_set(retain, applied, changes)
        actions = [
            change_id for change_id in reversed(order)
            if change_id in applied and change_id not in locked
        ]
    else:
        # Applied entries satisfy dependencies and consume no new budget.
        actions = [change_id for change_id in order if change_id not in applied]
        units = sum(units_by_id[change_id] for change_id in actions)
        if units > budget:
            return failure("budget-exceeded")
        return success(actions, units)
    return success(actions, sum(units_by_id[change_id] for change_id in actions))

policy.py.text:
"""Validate release policy before computing actions.

G2 freezes production entirely, so policy short-circuits production
requests with `production-frozen` before any graph or change validation.
Staging plans are capped at STAGING_PLAN_LIMIT regardless of the requested
budget; staging rollback is not capped.
"""

ENVIRONMENTS = ("staging", "production")
SUPPORTED_ACTIONS = ("plan", "rollback")
STAGING_PLAN_LIMIT = 3


class PolicyError(ValueError):
    pass


def freeze(request):
    """Refuse production actions before graph or change validation."""
    if request.get("environment") == "production":
        raise PolicyError("production-frozen")


def limit_for(request):
    """Validate environment, action and budget; return the budget limit."""
    environment = request.get("environment")
    if environment not in ENVIRONMENTS:
        raise PolicyError("invalid-environment")
    if request.get("action") not in SUPPORTED_ACTIONS:
        raise PolicyError("unsupported-action")
    budget = request.get("budget")
    if type(budget) is not int or budget < 0:
        raise PolicyError("invalid-budget")
    if environment == "staging":
        # The owner revision caps staging plans even when the request allows more.
        return min(budget, STAGING_PLAN_LIMIT)
    return budget

