"""Normalize release records and the persisted journal at the input boundary.

This module owns input validation, record identity and replay data. It never
builds a graph and never decides ordering; it only turns raw JSON into
normalized, deduplicated records the planner can trust.
"""


class JournalError(ValueError):
    pass


def _is_text(value):
    return isinstance(value, str) and value != ""


def _read_depends_on(row):
    # `depends_on` defaults to an empty array when absent. An explicit null is
    # treated the same way, matching `applied`; use `row.get` so a missing key
    # never raises KeyError and both spellings of "no dependencies" agree.
    deps = row.get("depends_on")
    if deps is None:
        return []
    if not isinstance(deps, list):
        raise JournalError("invalid-change")
    for dep in deps:
        if not _is_text(dep):
            raise JournalError("invalid-change")
    # Dependencies are a set semantically: duplicates and order carry no
    # meaning, so normalize now and make every later comparison set-based.
    return sorted(set(deps))


def _read_record(row):
    if not isinstance(row, dict):
        raise JournalError("invalid-change")
    # `type(x) is int` rather than isinstance: booleans subclass int in Python
    # and SPEC explicitly excludes them from integers.
    if (not _is_text(row.get("id"))
            or not _is_text(row.get("component"))
            or type(row.get("units")) is not int
            or row["units"] < 1):
        raise JournalError("invalid-change")
    return {
        "id": row["id"],
        "component": row["component"],
        "units": row["units"],
        "depends_on": _read_depends_on(row),
    }


def _identity(change):
    return (change["id"], change["component"], change["units"],
            frozenset(change["depends_on"]))


def read_changes(records):
    """Validate, normalize and deduplicate `changes`.

    Identical duplicates collapse to one before accounting and graph
    construction; two records sharing an ID but differing in component, units
    or dependency set are ambiguous and fail as `conflicting-change`.
