        if previous is None:
            by_id[change["id"]] = change
        elif _identity(previous) != _identity(change):
            raise JournalError("conflicting-change")
        # Identical duplicate: keep the first, drop the rest. Dependency
        # targets are validated later by the graph builder, which is the only
        # place that knows the complete set of valid IDs.
    return list(by_id.values())


def read_applied(applied):
    """Validate the caller-supplied persisted release journal.

    `applied` is absent -> empty journal. Semantically it is a set of change
    IDs, so repeats are harmless and collapse. Shape errors are the caller's
    mistake (`invalid-change`); unknown IDs can only be detected once the full
    ID set is known, so the planner raises `unknown-dependency` for those.
    """
    if applied is None:
        return []
    if not isinstance(applied, list):
        raise JournalError("invalid-change")
    seen = set()
    ordered = []
    for entry in applied:
        if not _is_text(entry):
            raise JournalError("invalid-change")
        if entry not in seen:
            seen.add(entry)
            ordered.append(entry)
    return ordered


def read_retain(retain, applied):
    """Validate the shape of the staging rollback `retain` list (G2).

    `retain` names applied change IDs that must stay installed. It is only
    meaningful for rollback, so its default is an empty list and the planner
    passes it only for that action - a stray `retain` on a plan request is
    ignored rather than rejected, so plan behavior is unchanged from G1.

    This function checks shape only. Membership ("already applied") is checked
    later by the planner, on purpose: whether an ID is *declared* is only known
    after the change set is read, and G2's graph/journal errors must keep their
    precedence. Checking "applied" here would turn an undeclared retain ID into
    `invalid-retain` even when the real problem is an unknown ID elsewhere.
    """
