"""Compose policy and journal data into a plan."""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, limit_for, within_budget


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def _validate_graph(changes, applied):
    """Reject graphs that cannot be ordered or replayed.

    Order matters: dependency targets are checked before cycles. A cycle whose
    members are all already applied must still be reported as dependency-cycle,
    so cycle detection runs over the full graph rather than over unapplied
    nodes only. Applied IDs are verified against definitions because rollback
    and dependency replay both need a unit count for them.
    """
    known = {row["id"] for row in changes}
    if not applied <= known:
        raise JournalError("unknown-dependency")
    for row in changes:
        if not row["depends_on"] <= known:
            raise JournalError("unknown-dependency")


def topological_order(changes):
    """Kahn's algorithm, tie-broken lexicographically among eligible nodes.

    Determinism is required because rollback mirrors this exact sequence in
    reverse; using a heap instead of sorting once keeps the "currently
    eligible" semantics that SPEC.md:13 asks for.
    """
    pending = {row["id"]: set(row["depends_on"]) for row in changes}
    blocked_by = {change_id: 0 for change_id in pending}
    dependents = {change_id: [] for change_id in pending}
    for change_id, deps in pending.items():
        blocked_by[change_id] = len(deps)
        for dep in deps:
            dependents[dep].append(change_id)
    ready = [change_id for change_id, count in blocked_by.items() if count == 0]
    heapq.heapify(ready)
    order = []
    while ready:
        current = heapq.heappop(ready)
        order.append(current)
        for dependent in dependents[current]:
            blocked_by[dependent] -= 1
            if blocked_by[dependent] == 0:
                heapq.heappush(ready, dependent)
    if len(order) != len(pending):
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        action, budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request)
        _validate_graph(changes, applied)
        order = topological_order(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    units_by_id = {row["id"]: row["units"] for row in changes}
    if action == "rollback":
        # Reverse of the full order, applied entries only, budget uncapped.
        actions = [change_id for change_id in reversed(order) if change_id in applied]
    else:
        # Applied entries satisfy dependencies but are neither emitted nor charged.
        actions = [change_id for change_id in order if change_id not in applied]
    units = sum(units_by_id[change_id] for change_id in actions)
    # Budget is checked on emitted units only, i.e. after replay and dedup.
    if not within_budget(action, units, budget):
        return failure("budget-exceeded")
    return {"status": "ok", "actions": actions, "units": units}

