ID_FIELDS = ("id", "component")


class JournalError(ValueError):
    pass


def _is_id(value):
    return isinstance(value, str) and bool(value)


def _id_list(value):
    if not isinstance(value, list):
        raise JournalError("invalid-change")
    for item in value:
        if not _is_id(item):
            raise JournalError("invalid-change")
    return value


def _change(row):
    if not isinstance(row, dict):
        raise JournalError("invalid-change")
    for field in ID_FIELDS:
        if not _is_id(row.get(field)):
            raise JournalError("invalid-change")
    units = row.get("units")
    if type(units) is not int or units < 1:
        raise JournalError("invalid-change")
    depends_on = row.get("depends_on", [])
    if not isinstance(depends_on, list):
        raise JournalError("invalid-change")
    return {
        "id": row["id"],
        "component": row["component"],
        "units": units,
        "depends_on": frozenset(_id_list(depends_on)),
    }


def read_changes(records):
    """Validate change records and collapse identical duplicates."""
    if not isinstance(records, list):
        raise JournalError("invalid-change")
    changes = {}
    for row in records:
        change = _change(row)
        seen = changes.get(change["id"])
        if seen is None:
            changes[change["id"]] = change
        elif seen != change:
            raise JournalError("conflicting-change")
    return [changes[key] for key in sorted(changes)]


def read_applied(values):
    """Validate the persisted release journal, keeping a set of change IDs."""
    return set(_id_list(values if values is not None else []))

