"""Compose policy and journal data into a plan."""
from heapq import heapify, heappop, heappush

from journal import JournalError, read_applied, read_changes, read_retain
from policy import PolicyError, freeze_of, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def topological_order(changes):
    """Deterministic order: smallest eligible ID first, dependencies before dependents."""
    known = {change["id"]: change for change in changes}
    dependents = {key: [] for key in known}
    pending = {}
    for change in changes:
        for dependency in change["depends_on"]:
            if dependency not in known:
                raise JournalError("unknown-dependency")
            dependents[dependency].append(change["id"])
        pending[change["id"]] = len(change["depends_on"])
    ready = [key for key, count in pending.items() if count == 0]
    heapify(ready)
    order = []
    while ready:
        key = heappop(ready)
        order.append(key)
        for dependent in dependents[key]:
            pending[dependent] -= 1
            if pending[dependent] == 0:
                heappush(ready, dependent)
    if len(order) != len(known):
        raise JournalError("dependency-cycle")
    return order


def retained_closure(seeds, applied_changes, applied):
    """Retained IDs plus applied transitive dependencies required by them."""
    keep = set()
    pending = list(seeds)
    while pending:
        key = pending.pop()
        if key in keep:
            continue
        keep.add(key)
        for dependency in applied_changes[key]["depends_on"]:
            if dependency in applied:
                pending.append(dependency)
    return keep


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        freeze_of(request)
        action, budget = limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request.get("applied"))
        retain = read_retain(request) if action == "rollback" else []
        order = topological_order(changes)
        if applied - set(order):
            raise JournalError("unknown-dependency")
        if retain and set(retain) - applied:
            raise JournalError("invalid-retain")
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    units_of = {change["id"]: change["units"] for change in changes}
    if action == "rollback":
        keep = retained_closure(retain, {c["id"]: c for c in changes}, applied)
        actions = [key for key in reversed(order) if key in applied and key not in keep]
    else:
        actions = [key for key in order if key not in applied]
    units = sum(units_of[key] for key in actions)
    if action == "plan" and units > budget:
        return failure("budget-exceeded")
    return {"status": "ok", "actions": actions, "units": units}

