"""Compose policy and journal data into a plan.

Dependency direction: ``release -> planner -> {policy, journal}``.  This is the
only module that reads both policy and journal data; every rejection is turned
into a JSON result here so that ``release`` stays pure transport.
"""
from journal import (JournalError, _MISSING, build_graph, read_changes,
                     read_journal, topological_order)
from policy import PolicyError, limit_for


def failure(code):
    # Failures are built in exactly one place so that "a disallowed operation
    # emits no partial actions" cannot be broken by a caller-side shortcut.
    return {"status": "error", "error": code, "actions": [], "units": 0}


def plan(request):
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        budget = limit_for(request)
        # Deduplication happens inside read_changes, i.e. *before* accounting
        # and graph construction, so a duplicated record never double-counts.
        changes = read_changes(request.get("changes"))
        applied = read_journal(request.get("applied", _MISSING), changes)
        graph = build_graph(changes)
        order = topological_order(changes, graph)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))

    action = request["action"]
    by_id = {row["id"]: row for row in changes}
    if action == "plan":
        # Already-applied entries still satisfy dependencies for their
        # dependents, but they are not re-emitted and consume no new budget.
        emitted = [name for name in order if name not in applied]
        units = sum(by_id[name]["units"] for name in emitted)
        if units > budget:
            # Checked against the total *after* replay, before emitting anything,
            # so a denied plan never yields partial actions.
            return failure("budget-exceeded")
    else:  # rollback
        # Reverse of the FULL topological order, keeping only applied entries.
        # Re-sorting the applied subgraph would let nodes that are not rolling
        # back shift the relative order of ones that are.
        emitted = [name for name in reversed(order) if name in applied]
        units = sum(by_id[name]["units"] for name in emitted)
        # budget was validated by limit_for but does not cap rollback: a
        # rollback can never wait on budget without leaving the release broken.
    return {"status": "ok", "actions": emitted, "units": units}

