"""Compose policy and journal data into a plan.

Import direction: planner depends on journal and policy; neither imports back.
Planner owns the dependency graph, the deterministic order, and the single
place where success/failure objects are assembled.
"""
import heapq

from journal import JournalError, read_applied, read_changes
from policy import PolicyError, limit_for


def failure(code):
    return {"status": "error", "error": code, "actions": [], "units": 0}


def check_dependencies(changes):
    """Reject dangling dependency targets before ordering.

    A dependency naming an ID that no record declares can never become eligible,
    so it is reported as ``unknown-dependency`` instead of being confused with a
    cycle.
    """
    known = {change["id"] for change in changes}
    for change in changes:
        for target in change["depends_on"]:
            if target not in known:
                raise JournalError("unknown-dependency")


def topological_order(changes):
    """Return the full deterministic order of every change.

    Ties among currently eligible changes are broken by lexicographic ID via a
    heap, so the order is a pure function of the declared graph. Excess nodes
    left after the sweep mean a cycle reachable anywhere in the graph, which is
    a fatal ``dependency-cycle`` rather than a partial order.
    """
    pending = {}
    dependents = {change["id"]: [] for change in changes}
    for change in changes:
        pending[change["id"]] = len(change["depends_on"])
        for target in change["depends_on"]:
            dependents[target].append(change["id"])
    eligible = [change_id for change_id, count in pending.items() if count == 0]
    heapq.heapify(eligible)
    order = []
    while eligible:
        current = heapq.heappop(eligible)
        order.append(current)
        for dependent in dependents[current]:
            pending[dependent] -= 1
            if pending[dependent] == 0:
                heapq.heappush(eligible, dependent)
    if len(order) != len(changes):
        raise JournalError("dependency-cycle")
    return order


def plan(request):
    """Handle one plan or rollback request.

    Only the action policy is consulted before data validation; budget is the
    last check so that malformed or cyclic input is reported with its own code
    instead of a budget error.
    """
    if not isinstance(request, dict):
        return failure("invalid-request")
    try:
        limit_for(request)
        changes = read_changes(request.get("changes"))
        applied = read_applied(request, changes)
        check_dependencies(changes)
        order = topological_order(changes)
    except (PolicyError, JournalError) as exc:
        return failure(str(exc))
    units_by_id = {change["id"]: change["units"] for change in changes}
    if request.get("action") == "rollback":
        # Rollback undoes persisted releases in reverse dependency order. The
        # budget was validated but must not cap it; otherwise a smaller budget
        # could strand a half-rolled-back environment.
        actions = [change_id for change_id in reversed(order) if change_id in applied]
    else:
        # Replay first: applied entries satisfy dependencies and are absent from
        # the output, so they never consume new budget.
        actions = [change_id for change_id in order if change_id not in applied]
        units = sum(units_by_id[change_id] for change_id in actions)
        if units > limit_for(request):
            return failure("budget-exceeded")
    return {"status": "ok", "actions": actions,
            "units": sum(units_by_id[change_id] for change_id in actions)}

